#include <string>
#include <fstream>

class INIWriter {
public:
    INIWriter() {}

    static void write(const std::string& filepath, const INIReader& reader, const bool overwrite = false) {
        if (!overwrite && std::ifstream(filepath).good()) {
            throw std::runtime_error("file: " + filepath + " already exists.");
        }

        std::ofstream outfile(filepath);
        if (!outfile.is_open()) {
            throw std::runtime_error("cannot open output file: " + filepath);
        }

        for (const auto& section : reader.Sections()) {
            outfile << "[" << section << "]\n";
            for (const auto& key : reader.Keys(section)) {
                outfile << key << "=" << reader.Get(section, key) << "\n";
            }
        }
    }
};
